     1|/**
     2| * Production-grade chat send queue with request IDs, retry, timeout,
     3| * duplicate prevention, pending-message recovery, background/resume handling,
     4| * and full stream lifecycle logging.
     5| *
     6| * Replaces the fragile `messageSendPending` boolean with a deterministic
     7| * state machine per send operation.
     8| */
     9|
    10|import AsyncStorage from '@react-native-async-storage/async-storage';
    11|import { AppState, type AppStateStatus } from 'react-native';
    12|import { ivxChatService } from '@/src/modules/ivx-owner-ai/services/ivxChatService';
    13|import type { ChatReplyContext } from '@/src/modules/chat/types/chat';
    14|
    15|export type SendOperationStatus =
    16|  | 'queued'
    17|  | 'sending'
    18|  | 'retrying'
    19|  | 'sent'
    20|  | 'failed'
    21|  | 'cancelled';
    22|
    23|export type SendOperationMode = 'send_only' | 'send_and_ai' | 'ai_only' | 'attachment';
    24|
    25|export type SendOperation = {
    26|  requestId: string;
    27|  clientId: string;
    28|  text: string;
    29|  mode: SendOperationMode;
    30|  replyTo: ChatReplyContext | null;
    31|  senderLabel: string;
    32|  status: SendOperationStatus;
    33|  createdAt: number;
    34|  sentAt: number | null;
    35|  failedAt: number | null;
    36|  attempts: number;
    37|  maxAttempts: number;
    38|  lastError: string | null;
    39|  lastErrorDetail: string | null;
    40|  timeoutAt: number;
    41|  nextRetryAt: number | null;
    42|  retryDelayMs: number;
    43|  upload: { uri: string; name: string; type: string | null; size: number | null } | null;
    44|};
    45|
    46|export type TransportQueueState = {
    47|  operations: SendOperation[];
    48|  isProcessing: boolean;
    49|  lastProcessedAt: number | null;
    50|};
    51|
    52|export type TransportLifecycleEvent =
    53|  | { type: 'request_started'; requestId: string; attempt: number; timestamp: number }
    54|  | { type: 'token_attached'; requestId: string; timestamp: number }
    55|  | { type: 'request_sent'; requestId: string; timestamp: number }
    56|  | { type: 'stream_opened'; requestId: string; timestamp: number }
    57|  | { type: 'chunk_received'; requestId: string; timestamp: number; bytes: number }
    58|  | { type: 'stream_closed'; requestId: string; timestamp: number; durationMs: number }
    59|  | { type: 'timeout'; requestId: string; timestamp: number; timeoutMs: number }
    60|  | { type: 'retry'; requestId: string; timestamp: number; attempt: number; delayMs: number; reason: string }
    61|  | { type: 'failed'; requestId: string; timestamp: number; error: string; detail: string; final: boolean }
    62|  | { type: 'sent'; requestId: string; timestamp: number; durationMs: number; messageId: string };
    63|
    64|/**
    65| * React Native (Hermes on Android) does not expose `DOMException` as a
    66| * global. Touching it throws `ReferenceError: Property 'DOMException'
    67| * doesn't exist` and killed the send pipeline after BACKEND_POST_FINISHED.
    68| * Use a tagged Error fallback so all `name === 'AbortError'` checks keep
    69| * working across web, iOS, and Android.
    70| */
    71|class AbortLikeError extends Error {
    72|  constructor(message: string = 'Aborted') {
    73|    super(message);
    74|    this.name = 'AbortError';
    75|  }
    76|}
    77|function createAbortError(message: string = 'Aborted'): Error {
    78|  const DOMExceptionRef = (globalThis as { DOMException?: new (msg: string, name: string) => Error }).DOMException;
    79|  if (typeof DOMExceptionRef === 'function') {
    80|    try { return new DOMExceptionRef(message, 'AbortError'); } catch { /* fall through */ }
    81|  }
    82|  return new AbortLikeError(message);
    83|}
    84|function isAbortError(error: unknown): boolean {
    85|  if (!error || typeof error !== 'object') return false;
    86|  return (error as { name?: string }).name === 'AbortError';
    87|}
    88|
    89|const PERSISTENCE_KEY = 'ivx_chat_transport_queue_v1';
    90|const QUEUE_TIMEOUT_MS = 30_000;
    91|const MAX_RETRY_ATTEMPTS = 3;
    92|const BASE_RETRY_DELAY_MS = 1_000;
    93|const MAX_RETRY_DELAY_MS = 8_000;
    94|const RETRY_STATUS_CODES = new Set([429, 502, 503, 504]);
    95|const RETRY_ERROR_PATTERNS = [
    96|  /network request failed/i,
    97|  /failed to fetch/i,
    98|  /load failed/i,
    99|  /timed? out/i,
   100|  /timeout/i,
   101|  /econnreset/i,
   102|  /ENOTFOUND/i,
   103|  /ECONNREFUSED/i,
   104|];
   105|
   106|let queueState: TransportQueueState = {
   107|  operations: [],
   108|  isProcessing: false,
   109|  lastProcessedAt: null,
   110|};
   111|
   112|const stateListeners = new Set<(state: TransportQueueState) => void>();
   113|const lifecycleListeners = new Set<(event: TransportLifecycleEvent) => void>();
   114|let processTimer: ReturnType<typeof setTimeout> | null = null;
   115|let persistTimer: ReturnType<typeof setTimeout> | null = null;
   116|let appStateSubscription: { remove: () => void } | null = null;
   117|let initialized = false;
   118|
   119|function now(): number {
   120|  return Date.now();
   121|}
   122|
   123|function generateRequestId(): string {
   124|  const cryptoRef = globalThis.crypto as { randomUUID?: () => string } | undefined;
   125|  if (cryptoRef?.randomUUID) {
   126|    return `req-${cryptoRef.randomUUID()}`;
   127|  }
   128|  return `req-${now()}-${Math.random().toString(36).slice(2, 10)}`;
   129|}
   130|
   131|function computeRetryDelay(attempt: number): number {
   132|  const exp = Math.min(MAX_RETRY_DELAY_MS, BASE_RETRY_DELAY_MS * Math.pow(2, attempt - 1));
   133|  return Math.floor(Math.random() * exp) + BASE_RETRY_DELAY_MS;
   134|}
   135|
   136|function isRetryableError(error: unknown): { retry: boolean; reason: string } {
   137|  if (isAbortError(error)) {
   138|    return { retry: false, reason: 'aborted' };
   139|  }
   140|
   141|  const message = error instanceof Error ? error.message : String(error);
   142|  const lowerMessage = message.toLowerCase();
   143|
   144|  for (const pattern of RETRY_ERROR_PATTERNS) {
   145|    if (pattern.test(lowerMessage)) {
   146|      return { retry: true, reason: 'network_transient' };
   147|    }
   148|  }
   149|
   150|  const statusMatch = lowerMessage.match(/(?:status|http)\s*[:=]?\s*(\d{3})/);
   151|  if (statusMatch) {
   152|    const status = parseInt(statusMatch[1]!, 10);
   153|    if (RETRY_STATUS_CODES.has(status)) {
   154|      return { retry: true, reason: `http_${status}` };
   155|    }
   156|    if (status >= 400 && status < 500) {
   157|      return { retry: false, reason: `client_error_${status}` };
   158|    }
   159|    if (status >= 500) {
   160|      return { retry: true, reason: `server_error_${status}` };
   161|    }
   162|  }
   163|
   164|  if (lowerMessage.includes('supabase') && lowerMessage.includes('unavailable')) {
   165|    return { retry: true, reason: 'supabase_transient' };
   166|  }
   167|
   168|  return { retry: false, reason: 'non_retryable' };
   169|}
   170|
   171|function buildTechnicalError(operation: SendOperation): string {
   172|  const base = operation.lastError ?? 'Unknown error';
   173|  const detail = operation.lastErrorDetail ?? '';
   174|  const attempts = operation.attempts;
   175|  const maxAttempts = operation.maxAttempts;
   176|
   177|  if (attempts >= maxAttempts) {
   178|    if (detail.includes('timeout') || detail.includes('aborted')) {
   179|      return `Request timed out after ${attempts} attempts. The server may be temporarily overloaded or unreachable. Please check your connection and try again.`;
   180|    }
   181|    if (detail.includes('401') || detail.includes('403') || base.includes('401') || base.includes('403')) {
   182|      return `Authentication failed after ${attempts} attempts. Your session may have expired. Please sign in again.`;
   183|    }
   184|    if (detail.includes('500') || base.includes('500')) {
   185|      return `Server error after ${attempts} attempts. The backend encountered an internal problem. This has been logged. Please try again shortly.`;
   186|    }
   187|    return `Send failed after ${attempts} attempts. Last error: ${base}${detail ? ` (${detail})` : ''}`;
   188|  }
   189|
   190|  return base;
   191|}
   192|
   193|function emitLifecycle(event: TransportLifecycleEvent): void {
   194|  lifecycleListeners.forEach((listener) => {
   195|    try { listener(event); } catch (e) { /* swallow */ }
   196|  });
   197|}
   198|
   199|function emitState(): void {
   200|  const snapshot = { ...queueState, operations: [...queueState.operations] };
   201|  stateListeners.forEach((listener) => {
   202|    try { listener(snapshot); } catch (e) { /* swallow */ }
   203|  });
   204|}
   205|
   206|async function persistQueue(): Promise<void> {
   207|  try {
   208|    const storable = queueState.operations.filter(
   209|      (op) => op.status === 'queued' || op.status === 'sending' || op.status === 'retrying'
   210|    );
   211|    if (storable.length === 0) {
   212|      await AsyncStorage.removeItem(PERSISTENCE_KEY);
   213|      return;
   214|    }
   215|    await AsyncStorage.setItem(PERSISTENCE_KEY, JSON.stringify({
   216|      operations: storable,
   217|      savedAt: now(),
   218|    }));
   219|  } catch (error) {
   220|    console.log('[ChatTransportQueue] Persist failed:', error instanceof Error ? error.message : 'unknown');
   221|  }
   222|}
   223|
   224|export async function restorePendingQueue(): Promise<SendOperation[]> {
   225|  try {
   226|    const raw = await AsyncStorage.getItem(PERSISTENCE_KEY);
   227|    if (!raw) return [];
   228|    const parsed = JSON.parse(raw) as { operations?: SendOperation[]; savedAt?: number };
   229|    if (!Array.isArray(parsed.operations)) return [];
   230|
   231|    const restored = parsed.operations.map((op) => ({
   232|      ...op,
   233|      status: 'queued' as SendOperationStatus,
   234|      attempts: 0,
   235|      timeoutAt: now() + QUEUE_TIMEOUT_MS,
   236|      nextRetryAt: null,
   237|      lastError: null,
   238|      lastErrorDetail: null,
   239|    }));
   240|
   241|    console.log('[ChatTransportQueue] Restored', restored.length, 'pending operations from', new Date(parsed.savedAt ?? 0).toISOString());
   242|    return restored;
   243|  } catch (error) {
   244|    console.log('[ChatTransportQueue] Restore failed:', error instanceof Error ? error.message : 'unknown');
   245|    return [];
   246|  }
   247|}
   248|
   249|function schedulePersist(): void {
   250|  if (persistTimer) clearTimeout(persistTimer);
   251|  persistTimer = setTimeout(() => {
   252|    void persistQueue();
   253|  }, 300);
   254|}
   255|
   256|function removeOperation(requestId: string): void {
   257|  queueState.operations = queueState.operations.filter((op) => op.requestId !== requestId);
   258|  schedulePersist();
   259|  emitState();
   260|}
   261|
   262|function updateOperation(requestId: string, patch: Partial<SendOperation>): void {
   263|  queueState.operations = queueState.operations.map((op) =>
   264|    op.requestId === requestId ? { ...op, ...patch } : op
   265|  );
   266|  schedulePersist();
   267|  emitState();
   268|}
   269|
   270|async function executeSend(operation: SendOperation): Promise<{ messageId: string; conversationId: string }> {
   271|  const start = now();
   272|  const abortController = new AbortController();
   273|  const timeoutHandle = setTimeout(() => {
   274|    abortController.abort(createAbortError('Queue timeout'));
   275|  }, QUEUE_TIMEOUT_MS);
   276|
   277|  emitLifecycle({ type: 'request_started', requestId: operation.requestId, attempt: operation.attempts, timestamp: start });
   278|
   279|  try {
   280|    let result: { id: string; conversationId: string };
   281|
   282|    if (operation.mode === 'attachment' && operation.upload) {
   283|      emitLifecycle({ type: 'token_attached', requestId: operation.requestId, timestamp: now() });
   284|      const sent = await ivxChatService.sendOwnerAttachmentMessage({
   285|        upload: operation.upload,
   286|        body: operation.text,
   287|        senderLabel: operation.senderLabel,
   288|      });
   289|      result = { id: sent.id, conversationId: sent.conversationId };
   290|    } else {
   291|      emitLifecycle({ type: 'token_attached', requestId: operation.requestId, timestamp: now() });
   292|      const sent = await ivxChatService.sendOwnerTextMessage({
   293|        body: operation.text,
   294|        senderLabel: operation.senderLabel,
   295|        requireRemote: false,
   296|      });
   297|      result = { id: sent.id, conversationId: sent.conversationId };
   298|    }
   299|
   300|    clearTimeout(timeoutHandle);
   301|    const duration = now() - start;
   302|    emitLifecycle({ type: 'request_sent', requestId: operation.requestId, timestamp: now() });
   303|    emitLifecycle({ type: 'stream_closed', requestId: operation.requestId, timestamp: now(), durationMs: duration });
   304|    emitLifecycle({ type: 'sent', requestId: operation.requestId, timestamp: now(), durationMs: duration, messageId: result.id });
   305|
   306|    return { messageId: result.id, conversationId: result.conversationId };
   307|  } catch (error) {
   308|    clearTimeout(timeoutHandle);
   309|    const isTimeout = isAbortError(error);
   310|    if (isTimeout) {
   311|      emitLifecycle({ type: 'timeout', requestId: operation.requestId, timestamp: now(), timeoutMs: QUEUE_TIMEOUT_MS });
   312|    }
   313|    throw error;
   314|  }
   315|}
   316|
   317|async function processNext(): Promise<void> {
   318|  if (queueState.isProcessing) return;
   319|
   320|  const pending = queueState.operations.find((op) =>
   321|    op.status === 'queued' || op.status === 'sending' || op.status === 'retrying'
   322|  );
   323|  if (!pending) {
   324|    queueState.isProcessing = false;
   325|    queueState.lastProcessedAt = now();
   326|    emitState();
   327|    return;
   328|  }
   329|
   330|  queueState.isProcessing = true;
   331|  emitState();
   332|
   333|  const op = queueState.operations.find((o) => o.requestId === pending.requestId)!;
   334|
   335|  if (op.timeoutAt < now() && op.attempts >= op.maxAttempts) {
   336|    updateOperation(op.requestId, {
   337|      status: 'failed',
   338|      failedAt: now(),
   339|      lastError: 'Request expired after maximum retries.',
   340|      lastErrorDetail: `Timeout exceeded after ${op.attempts} attempts over ${now() - op.createdAt}ms.`,
   341|    });
   342|    emitLifecycle({
   343|      type: 'failed',
   344|      requestId: op.requestId,
   345|      timestamp: now(),
   346|      error: 'Request expired',
   347|      detail: `Timeout exceeded after ${op.attempts} attempts`,
   348|      final: true,
   349|    });
   350|    queueState.isProcessing = false;
   351|    processTimer = setTimeout(() => processNext(), 50);
   352|    return;
   353|  }
   354|
   355|  updateOperation(op.requestId, {
   356|    status: 'sending',
   357|    attempts: op.attempts + 1,
   358|    timeoutAt: now() + QUEUE_TIMEOUT_MS,
   359|  });
   360|
   361|  try {
   362|    const { messageId } = await executeSend(op);
   363|    updateOperation(op.requestId, {
   364|      status: 'sent',
   365|      sentAt: now(),
   366|      lastError: null,
   367|      lastErrorDetail: null,
   368|    });
   369|  } catch (error) {
   370|    const { retry, reason } = isRetryableError(error);
   371|    const isLastAttempt = op.attempts + 1 >= op.maxAttempts;
   372|    const shouldRetry = retry && !isLastAttempt;
   373|
   374|    if (shouldRetry) {
   375|      const delay = computeRetryDelay(op.attempts + 1);
   376|      updateOperation(op.requestId, {
   377|        status: 'retrying',
   378|        lastError: error instanceof Error ? error.message : String(error),
   379|        lastErrorDetail: reason,
   380|        nextRetryAt: now() + delay,
   381|        retryDelayMs: delay,
   382|      });
   383|      emitLifecycle({
   384|        type: 'retry',
   385|        requestId: op.requestId,
   386|        timestamp: now(),
   387|        attempt: op.attempts + 1,
   388|        delayMs: delay,
   389|        reason,
   390|      });
   391|      processTimer = setTimeout(() => processNext(), delay);
   392|      queueState.isProcessing = false;
   393|      return;
   394|    }
   395|
   396|    const errorMessage = error instanceof Error ? error.message : String(error);
   397|    updateOperation(op.requestId, {
   398|      status: 'failed',
   399|      failedAt: now(),
   400|      lastError: errorMessage,
   401|      lastErrorDetail: reason,
   402|    });
   403|    emitLifecycle({
   404|      type: 'failed',
   405|      requestId: op.requestId,
   406|      timestamp: now(),
   407|      error: errorMessage,
   408|      detail: reason,
   409|      final: true,
   410|    });
   411|  }
   412|
   413|  queueState.isProcessing = false;
   414|  processTimer = setTimeout(() => processNext(), 50);
   415|}
   416|
   417|export function enqueueSend(input: {
   418|  text: string;
   419|  mode: SendOperationMode;
   420|  replyTo: ChatReplyContext | null;
   421|  senderLabel: string;
   422|  upload?: { uri: string; name: string; type: string | null; size: number | null } | null;
   423|  clientId?: string;
   424|}): string {
   425|  const requestId = generateRequestId();
   426|  const operation: SendOperation = {
   427|    requestId,
   428|    clientId: input.clientId ?? `client-${now()}-${Math.random().toString(36).slice(2, 8)}`,
   429|    text: input.text,
   430|    mode: input.mode,
   431|    replyTo: input.replyTo ?? null,
   432|    senderLabel: input.senderLabel,
   433|    status: 'queued',
   434|    createdAt: now(),
   435|    sentAt: null,
   436|    failedAt: null,
   437|    attempts: 0,
   438|    maxAttempts: MAX_RETRY_ATTEMPTS,
   439|    lastError: null,
   440|    lastErrorDetail: null,
   441|    timeoutAt: now() + QUEUE_TIMEOUT_MS,
   442|    nextRetryAt: null,
   443|    retryDelayMs: 0,
   444|    upload: input.upload ?? null,
   445|  };
   446|
   447|  queueState.operations.push(operation);
   448|  schedulePersist();
   449|  emitState();
   450|
   451|  if (processTimer) clearTimeout(processTimer);
   452|  processTimer = setTimeout(() => processNext(), 50);
   453|
   454|  return requestId;
   455|}
   456|
   457|export function cancelSend(requestId: string): void {
   458|  const op = queueState.operations.find((o) => o.requestId === requestId);
   459|  if (!op) return;
   460|  updateOperation(requestId, { status: 'cancelled' });
   461|  emitLifecycle({ type: 'failed', requestId, timestamp: now(), error: 'Cancelled by user', detail: 'user_cancel', final: true });
   462|}
   463|
   464|export function retrySend(requestId: string): void {
   465|  const op = queueState.operations.find((o) => o.requestId === requestId);
   466|  if (!op) return;
   467|  updateOperation(requestId, {
   468|    status: 'queued',
   469|    attempts: 0,
   470|    lastError: null,
   471|    lastErrorDetail: null,
   472|    timeoutAt: now() + QUEUE_TIMEOUT_MS,
   473|    nextRetryAt: null,
   474|  });
   475|  if (processTimer) clearTimeout(processTimer);
   476|  processTimer = setTimeout(() => processNext(), 50);
   477|}
   478|
   479|export function dismissOperation(requestId: string): void {
   480|  removeOperation(requestId);
   481|}
   482|
   483|export function getQueueState(): TransportQueueState {
   484|  return { ...queueState, operations: [...queueState.operations] };
   485|}
   486|
   487|export function isQueueBusy(): boolean {
   488|  return queueState.operations.some((op) =>
   489|    op.status === 'queued' || op.status === 'sending' || op.status === 'retrying'
   490|  );
   491|}
   492|
   493|export function getFailedOperations(): SendOperation[] {
   494|  return queueState.operations.filter((op) => op.status === 'failed');
   495|}
   496|
   497|export function getTechnicalErrorFor(requestId: string): string | null {
   498|  const op = queueState.operations.find((o) => o.requestId === requestId);
   499|  if (!op || op.status !== 'failed') return null;
   500|  return buildTechnicalError(op);
   501|}
   502|
   503|export function subscribeToQueueState(listener: (state: TransportQueueState) => void): () => void {
   504|  stateListeners.add(listener);
   505|  listener(getQueueState());
   506|  return () => { stateListeners.delete(listener); };
   507|}
   508|
   509|export function subscribeToLifecycle(listener: (event: TransportLifecycleEvent) => void): () => void {
   510|  lifecycleListeners.add(listener);
   511|  return () => { lifecycleListeners.delete(listener); };
   512|}
   513|
   514|function handleAppStateChange(nextState: AppStateStatus): void {
   515|  if (nextState === 'active') {
   516|    console.log('[ChatTransportQueue] App resumed — checking for stuck operations');
   517|    const stuck = queueState.operations.filter((op) =>
   518|      op.status === 'sending' && op.timeoutAt < now()
   519|    );
   520|    stuck.forEach((op) => {
   521|      updateOperation(op.requestId, {
   522|        status: 'queued',
   523|        attempts: op.attempts,
   524|        lastError: 'Recovered after background timeout',
   525|        lastErrorDetail: 'app_resume_recovery',
   526|        timeoutAt: now() + QUEUE_TIMEOUT_MS,
   527|      });
   528|    });
   529|    if (stuck.length > 0) {
   530|      if (processTimer) clearTimeout(processTimer);
   531|      processTimer = setTimeout(() => processNext(), 50);
   532|    }
   533|  }
   534|}
   535|
   536|export async function initChatTransportQueue(): Promise<void> {
   537|  if (initialized) return;
   538|  initialized = true;
   539|
   540|  const restored = await restorePendingQueue();
   541|  if (restored.length > 0) {
   542|    queueState.operations = [...queueState.operations, ...restored];
   543|    emitState();
   544|    if (processTimer) clearTimeout(processTimer);
   545|    processTimer = setTimeout(() => processNext(), 100);
   546|  }
   547|
   548|  appStateSubscription = AppState.addEventListener('change', handleAppStateChange);
   549|}
   550|
   551|export function teardownChatTransportQueue(): void {
   552|  if (processTimer) {
   553|    clearTimeout(processTimer);
   554|    processTimer = null;
   555|  }
   556|  if (persistTimer) {
   557|    clearTimeout(persistTimer);
   558|    persistTimer = null;
   559|  }
   560|  appStateSubscription?.remove();
   561|  appStateSubscription = null;
   562|  initialized = false;
   563|  queueState.operations = [];
   564|  queueState.isProcessing = false;
   565|  queueState.lastProcessedAt = null;
   566|}

